self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("klg-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

function fromCache(request) {
  return caches.match(request, { ignoreSearch: true }).then((hit) => hit || (request.mode === "navigate" ? caches.match("./index.html") : undefined));
}

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET" || new URL(request.url).origin !== self.location.origin) return;
  event.respondWith(new Promise((resolve) => {
    let settled = false;
    const useCache = () => fromCache(request).then((hit) => { if (hit && !settled) { settled = true; resolve(hit); } return hit; });
    const timer = setTimeout(useCache, 4000);
    fetch(request)
      .then((response) => {
        clearTimeout(timer);
        if (response.ok && response.type === "basic") {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put(request.url.split("?")[0], copy));
        }
        if (!settled) { settled = true; resolve(response); }
      })
      .catch(() => {
        clearTimeout(timer);
        useCache().then((hit) => { if (!settled) { settled = true; resolve(hit || new Response("Offline and not saved yet", { status: 503 })); } });
      });
  }));
});
